import math


def scale_axes(rows):
    if not isinstance(rows, (list, tuple)):
        raise TypeError("rows must be a sequence")
    if not rows:
        return []
    if any(not isinstance(row, (list, tuple)) for row in rows):
        raise TypeError("each row must be a sequence")
    width = len(rows[0])
    if width == 0 or any(len(row) != width for row in rows):
        raise ValueError("rows must be nonempty and rectangular")
    if any(isinstance(value, bool) or not isinstance(value, (int, float))
           for row in rows for value in row):
        raise TypeError("coordinates must be numbers")
    if any(not math.isfinite(value) for row in rows for value in row):
        raise ValueError("coordinates must be finite")

    columns = list(zip(*rows))
    low = min(value for column in columns for value in column)
    high = max(value for column in columns for value in column)
    bounds = [(low, high) for column in columns]
    result = []
    for row in rows:
        scaled = []
        for value, (low, high) in zip(row, bounds):
            scaled.append(0.0 if low == high else (value - low) / (high - low))
        result.append(scaled)
    return result
```

